import sys

MOD = 998244353
G = 3
MAX_LOG = 20

roots = [0] * (MAX_LOG + 1)
iroots = [0] * (MAX_LOG + 1)
for i in range(1, MAX_LOG + 1):
    roots[i] = pow(G, (MOD - 1) >> i, MOD)
    iroots[i] = pow(roots[i], MOD - 2, MOD)

inv_sizes = [1] * (MAX_LOG + 1)
inv2 = (MOD + 1) // 2
for i in range(1, MAX_LOG + 1):
    inv_sizes[i] = inv_sizes[i - 1] * inv2 % MOD


def ntt(a):
    mod = MOD
    n = len(a)
    length = n
    log = n.bit_length() - 1
    rt = roots
    while length > 1:
        half = length >> 1
        wlen = rt[log]
        for i in range(0, n, length):
            w = 1
            end = i + half
            for j in range(i, end):
                u = a[j]
                v = a[j + half]
                x = u + v
                if x >= mod:
                    x -= mod
                y = u - v
                if y < 0:
                    y += mod
                a[j] = x
                a[j + half] = y * w % mod
                w = w * wlen % mod
        length = half
        log -= 1


def intt(a):
    mod = MOD
    n = len(a)
    length = 2
    log = 1
    irt = iroots
    while length <= n:
        half = length >> 1
        wlen = irt[log]
        for i in range(0, n, length):
            w = 1
            end = i + half
            for j in range(i, end):
                u = a[j]
                v = a[j + half] * w % mod
                x = u + v
                if x >= mod:
                    x -= mod
                y = u - v
                if y < 0:
                    y += mod
                a[j] = x
                a[j + half] = y
                w = w * wlen % mod
        length <<= 1
        log += 1
    inv_n = inv_sizes[n.bit_length() - 1]
    for i in range(n):
        a[i] = a[i] * inv_n % mod


def convolution(a, b):
    n = len(a)
    m = len(b)
    if n == 0 or m == 0:
        return []
    if min(n, m) <= 60:
        if n < m:
            a, b = b, a
            n, m = m, n
        res = [0] * (n + m - 1)
        mod = MOD
        for i in range(n):
            ai = a[i]
            if ai:
                for j in range(m):
                    res[i + j] = (res[i + j] + ai * b[j]) % mod
        return res

    z = n + m - 1
    sz = 1 << (z - 1).bit_length()
    a = a + [0] * (sz - n)
    b = b + [0] * (sz - m)
    ntt(a)
    ntt(b)
    mod = MOD
    for i in range(sz):
        a[i] = a[i] * b[i] % mod
    intt(a)
    return a[:z]


def fps_inv(f, n):
    g = [pow(f[0], MOD - 2, MOD)]
    m = 1
    while m < n:
        m2 = min(m * 2, n)
        fg = convolution(f[:m2], g)[:m2]
        for i in range(m2):
            if fg[i]:
                fg[i] = MOD - fg[i]
        fg[0] = (fg[0] + 2) % MOD
        g = convolution(g, fg)[:m2]
        m = m2
    return g


def solve():
    input = sys.stdin.readline
    N = int(input())
    S = input().strip()

    if S[0] != 'B' or S[-1] != 'W':
        print(0)
        return

    fact = [1] * (N + 1)
    for i in range(1, N + 1):
        fact[i] = fact[i - 1] * i % MOD
    invfact = [1] * (N + 1)
    invfact[N] = pow(fact[N], MOD - 2, MOD)
    for i in range(N, 0, -1):
        invfact[i - 1] = invfact[i] * i % MOD

    a_list = []
    w_list = []
    w = b = 0
    for i, ch in enumerate(S):
        if ch == 'B':
            if i == 0 or S[i - 1] == 'W':
                if b <= N - 1 and w >= b:
                    a_list.append(b)
                    w_list.append(w)
            b += 1
        else:
            w += 1

    m = len(a_list)
    if m == 0:
        print(0)
        return

    # Alternating BWBW...: inverse of factorial series.
    if m == N:
        ok = True
        for i in range(N):
            if a_list[i] != i or w_list[i] != i:
                ok = False
                break
        if ok:
            g = fps_inv(fact, N + 1)
            print((-g[N]) % MOD)
            return

    # Small case: direct O(m^2).
    if m <= 2000:
        dp = [0] * m
        dp[0] = 1
        for i in range(1, m):
            wi = w_list[i]
            s = 0
            for j in range(i):
                dj = dp[j]
                if dj:
                    s += dj * fact[wi - a_list[j]]
            dp[i] = (-s % MOD) * invfact[wi - a_list[i]] % MOD
        ans = 0
        for i in range(m):
            ans = (ans + dp[i] * fact[N - a_list[i]]) % MOD
        print(ans)
        return

    dp = [0] * m
    acc = [0] * m
    dp[0] = 1

    sys.setrecursionlimit(1_000_000)

    BLOCK = 64
    NAIVE_LIMIT = 50000

    def cdq(l, r):
        if r - l <= BLOCK:
            for i in range(l, r):
                if i == 0:
                    dp[i] = 1
                else:
                    dp[i] = (-acc[i] * invfact[w_list[i] - a_list[i]]) % MOD
                di = dp[i]
                if di:
                    ai = a_list[i]
                    for j in range(i + 1, r):
                        val = di * fact[w_list[j] - ai] % MOD
                        nv = acc[j] + val
                        if nv >= MOD:
                            nv -= MOD
                        acc[j] = nv
            return

        mid = (l + r) >> 1
        cdq(l, mid)

        left_count = mid - l
        right_count = r - mid
        if left_count and right_count:
            naive_cost = left_count * right_count
            min_a = a_list[l]
            max_a = a_list[mid - 1]
            max_w = w_list[r - 1]
            est_len = (max_a - min_a + 1) + (max_w - min_a + 1) - 1

            if naive_cost <= NAIVE_LIMIT or naive_cost <= (est_len * est_len.bit_length()) // 2:
                for j in range(l, mid):
                    dj = dp[j]
                    if dj:
                        aj = a_list[j]
                        for i in range(mid, r):
                            val = dj * fact[w_list[i] - aj] % MOD
                            nv = acc[i] + val
                            if nv >= MOD:
                                nv -= MOD
                            acc[i] = nv
            else:
                nz = []
                for j in range(l, mid):
                    dj = dp[j]
                    if dj:
                        nz.append((a_list[j], dj))
                if nz:
                    if len(nz) * right_count <= NAIVE_LIMIT:
                        for aj, dj in nz:
                            for i in range(mid, r):
                                val = dj * fact[w_list[i] - aj] % MOD
                                nv = acc[i] + val
                                if nv >= MOD:
                                    nv -= MOD
                                acc[i] = nv
                    else:
                        min_a = nz[0][0]
                        max_a = nz[-1][0]
                        x = [0] * (max_a - min_a + 1)
                        for aj, dj in nz:
                            x[aj - min_a] = dj
                        max_k = w_list[r - 1] - min_a
                        if max_k >= 0:
                            f = fact[:max_k + 1]
                            conv = convolution(x, f)
                            for i in range(mid, r):
                                val = conv[w_list[i] - min_a]
                                nv = acc[i] + val
                                if nv >= MOD:
                                    nv -= MOD
                                acc[i] = nv

        cdq(mid, r)

    cdq(0, m)

    ans = 0
    for i in range(m):
        ans = (ans + dp[i] * fact[N - a_list[i]]) % MOD
    print(ans)


