from typing import List

class Solution:
    def maxProduct(self, nums: List[int], k: int, limit: int) -> int:
        total = sum(nums)
        if abs(k) > total:
            return -1

        offset = total
        mask = (1 << (2 * offset + 1)) - 1
        target = 1 << (offset + k)

        # Positive-product DP:
        # dp0[p]: bitset of sums for non-empty subsequences with product p and even length
        # dp1[p]: bitset of sums for non-empty subsequences with product p and odd length
        dp0 = [0] * (limit + 1)
        dp1 = [0] * (limit + 1)
        active = []
        is_active = [False] * (limit + 1)
        has_zero = False

        for x in nums:
            if x == 0:
                has_zero = True
                continue

            if x == 1:
                # Snapshot to avoid using the same 1 more than once.
                old0 = dp0[:]
                old1 = dp1[:]

                for p in active:
                    b = old0[p]
                    if b:
                        nb = (b << 1) & mask
                        if nb:
                            dp1[p] |= nb

                    b = old1[p]
                    if b:
                        nb = b >> 1
                        if nb:
                            dp0[p] |= nb

                # Start a new subsequence with this 1.
                bit = 1 << (offset + 1)
                dp1[1] |= bit
                if not is_active[1]:
                    is_active[1] = True
                    active.append(1)

            else:
                if x > limit:
                    continue

                maxp = limit // x

                # Descending product order prevents reusing the current element.
                for p in range(maxp, 0, -1):
                    newp = p * x

                    b = dp0[p]
                    if b:
                        nb = (b << x) & mask
                        if nb:
                            dp1[newp] |= nb
                            if not is_active[newp]:
                                is_active[newp] = True
                                active.append(newp)

                    b = dp1[p]
                    if b:
                        nb = b >> x
                        if nb:
                            dp0[newp] |= nb
                            if not is_active[newp]:
                                is_active[newp] = True
                                active.append(newp)

                # Start a new subsequence with x.
                bit = 1 << (offset + x)
                dp1[x] |= bit
                if not is_active[x]:
                    is_active[x] = True
                    active.append(x)

        # Best positive product.
        for p in range(limit, 0, -1):
            if (dp0[p] | dp1[p]) & target:
                return p

        # Product 0 is possible only if a zero is included.
        if not has_zero:
            return -1
        if k == 0:
            return 0

        # DP for subsequences containing at least one zero.
        # n = no zero yet, z = has zero already.
        dp0n = dp1n = dp0z = dp1z = 0
        bit0 = 1 << offset

        for x in nums:
            old0n, old1n, old0z, old1z = dp0n, dp1n, dp0z, dp1z

            if x == 0:
                # Start with zero.
                dp1z |= bit0

                # Append zero to existing subsequences.
                if old0n:
                    dp1z |= old0n
                if old1n:
                    dp0z |= old1n
                if old0z:
                    dp1z |= old0z
                if old1z:
                    dp0z |= old1z
            else:
                # Start with positive x, still no zero.
                dp1n |= 1 << (offset + x)

                # Append positive x.
                if old0n:
                    dp1n |= (old0n << x) & mask
                if old1n:
                    dp0n |= old1n >> x

                if old0z:
                    dp1z |= (old0z << x) & mask
                if old1z:
                    dp0z |= old1z >> x

            if (dp0z | dp1z) & target:
                return 0

        return -1

import sys

INF = 10**30


def add_min(lst, cost, idx):
    for i in range(len(lst)):
        if lst[i][1] == idx:
            if cost < lst[i][0]:
                lst[i] = (cost, idx)
                if i == 1 and lst[1][0] < lst[0][0]:
                    lst[0], lst[1] = lst[1], lst[0]
            return

    if len(lst) < 2:
        lst.append((cost, idx))
        if len(lst) == 2 and lst[1][0] < lst[0][0]:
            lst[0], lst[1] = lst[1], lst[0]
    elif cost < lst[1][0]:
        lst[1] = (cost, idx)
        if lst[1][0] < lst[0][0]:
            lst[0], lst[1] = lst[1], lst[0]


def add_max(lst, val, idx):
    for i in range(len(lst)):
        if lst[i][1] == idx:
            if val > lst[i][0]:
                lst[i] = (val, idx)
                if i == 1 and lst[1][0] > lst[0][0]:
                    lst[0], lst[1] = lst[1], lst[0]
            return

    if len(lst) < 2:
        lst.append((val, idx))
        if len(lst) == 2 and lst[1][0] > lst[0][0]:
            lst[0], lst[1] = lst[1], lst[0]
    elif val > lst[1][0]:
        lst[1] = (val, idx)
        if lst[1][0] > lst[0][0]:
            lst[0], lst[1] = lst[1], lst[0]


def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    it = iter(data)
    T = next(it)
    ans = []

    for _ in range(T):
        N = next(it)
        K = next(it)

        vals = []
        m = [0] * N
        col = [0] * N

        for i in range(N):
            x = next(it)
            y = next(it)
            z = next(it)
            vals.append((x, y, z))

            if x >= y and x >= z:
                col[i] = 0
                mx = x
            elif y >= z:
                col[i] = 1
                mx = y
            else:
                col[i] = 2
                mx = z
            m[i] = mx

        M = 2 * K
        order = list(range(N))
        order.sort(key=m.__getitem__, reverse=True)
        selected = order[:M]

        selected_bool = [False] * N
        sum_m = 0
        parity = [0, 0, 0]

        for i in selected:
            selected_bool[i] = True
            sum_m += m[i]
            parity[col[i]] ^= 1

        if parity[0] == 0 and parity[1] == 0 and parity[2] == 0:
            ans.append(str(sum_m))
            continue

        # Top two selected items for each possible selected-item operation.
        # M_sel[c]: cost = m_i, for selected items whose initial color is c.
        # R_sel[c][t]: cost = m_i - value[i][t], recolor c -> t.
        M_sel = [[] for _ in range(3)]
        R_sel = [[[] for _ in range(3)] for __ in range(3)]

        for i in selected:
            c = col[i]
            mi = m[i]
            v = vals[i]
            add_min(M_sel[c], mi, i)
            for t in range(3):
                if t != c:
                    add_min(R_sel[c][t], mi - v[t], i)

        # Top two unselected items for each color value.
        U = [[] for _ in range(3)]
        for i in range(N):
            if not selected_bool[i]:
                v = vals[i]
                add_max(U[0], v[0], i)
                add_max(U[1], v[1], i)
                add_max(U[2], v[2], i)

        def pair_same_color(L1, L2):
            best = INF
            for c1, id1 in L1:
                for c2, id2 in L2:
                    if id1 != id2:
                        s = c1 + c2
                        if s < best:
                            best = s
            return best

        def pair_unselected(c1, c2):
            L1 = U[c1]
            L2 = U[c2]
            best = -1
            for v1, id1 in L1:
                for v2, id2 in L2:
                    if id1 != id2:
                        s = v1 + v2
                        if s > best:
                            best = s
            if best < 0:
                return None
            return best

        # Modes for one operation toggling colors p and q.
        # mode = (selected_color, selected_list, unselected_color_or_None)
        def modes(p, q):
            return [
                (p, R_sel[p][q], None),  # recolor p -> q
                (q, R_sel[q][p], None),  # recolor q -> p
                (p, M_sel[p], q),        # swap: remove selected p, add unselected q
                (q, M_sel[q], p),        # swap: remove selected q, add unselected p
            ]

        def single_cost(mode):
            _, sel_list, uc = mode
            if not sel_list:
                return INF
            cost = sel_list[0][0]
            if uc is not None:
                if not U[uc]:
                    return INF
                cost -= U[uc][0][0]
            return cost

        def pair_cost(mode1, mode2):
            sc1, l1, u1 = mode1
            sc2, l2, u2 = mode2

            if sc1 != sc2:
                if not l1 or not l2:
                    return INF
                sel = l1[0][0] + l2[0][0]
            else:
                sel = pair_same_color(l1, l2)
                if sel >= INF:
                    return INF

            if u1 is None:
                if u2 is None:
                    un = 0
                else:
                    if not U[u2]:
                        return INF
                    un = -U[u2][0][0]
            else:
                if u2 is None:
                    if not U[u1]:
                        return INF
                    un = -U[u1][0][0]
                else:
                    best_un = pair_unselected(u1, u2)
                    if best_un is None:
                        return INF
                    un = -best_un

            return sel + un

        odds = [c for c in range(3) if parity[c]]
        A, B = odds[0], odds[1]
        C = 3 - A - B

        min_cost = INF

        # One operation directly toggling the two odd colors.
        for mode in modes(A, B):
            c = single_cost(mode)
            if c < min_cost:
                min_cost = c

        # Two operations via the third color.
        for mode1 in modes(A, C):
            for mode2 in modes(B, C):
                c = pair_cost(mode1, mode2)
                if c < min_cost:
                    min_cost = c

        if min_cost < 0:
            min_cost = 0

        ans.append(str(sum_m - min_cost))

    sys.stdout.write("\n".join(ans))


if __name__ == "__main__":
    solve()

import sys

def solve():
    input = sys.stdin.readline
    line = input().strip()
    if not line:
        return
    N = int(line)
    S = input().strip()
    T = input().strip()

    req = [-1] * 26

    for s, t in zip(S, T):
        u = ord(s) - 97
        v = ord(t) - 97
        if req[u] == -1:
            req[u] = v
        elif req[u] != v:
            print(-1)
            return

    edges = []
    indeg = [0] * 26

    for i in range(26):
        if req[i] != -1 and req[i] != i:
            edges.append(i)
            indeg[req[i]] += 1

    edge_count = len(edges)

    state = [0] * 26
    pure_cycles = 0

    for start in edges:
        if state[start] != 0:
            continue

        cur = start
        path = []

        while True:
            if req[cur] == -1 or req[cur] == cur:
                break

            if state[cur] == 0:
                state[cur] = 1
                path.append(cur)
                cur = req[cur]
            elif state[cur] == 1:
                idx = path.index(cur)
                cycle = path[idx:]
                if all(indeg[v] == 1 for v in cycle):
                    pure_cycles += 1
                break
            else:
                break

        for v in path:
            state[v] = 2

    used_in_s = sum(1 for i in range(26) if req[i] != -1)
    used_in_t = len({req[i] for i in range(26) if req[i] != -1})

    if pure_cycles > 0 and used_in_s == 26 and used_in_t == 26:
        print(-1)
    else:
        print(edge_count + pure_cycles)

