import sys

def solve():
    data = sys.stdin.buffer.read().split()
    if not data:
        return

    t = int(data[0])
    idx = 1
    out = []
    SHIFT = 300000

    for _ in range(t):
        R = int(data[idx])
        B = int(data[idx + 1])
        idx += 2

        if R + B < 2 or R % 2 == 1 or (R == 0 and B % 2 == 1):
            out.append("No")
            continue

        out.append("Yes")

        if R == 0:
            k = B // 2

            for i in range(k):
                out.append(f"B {i + SHIFT} {i + SHIFT}")

            for i in range(k - 1, -1, -1):
                out.append(f"B {i + 1 + SHIFT} {i - 1 + SHIFT}")

        else:
            # A red cycle of even length R is used.
            # If B > 0, one red-red edge A -> C is replaced by a blue path.
            out.append(f"R {SHIFT} {SHIFT}")  # A

            if B > 0:
                if B % 2 == 1:
                    k = B // 2
                    for j in range(k + 1):
                        out.append(f"B {j + SHIFT} {j + 1 + SHIFT}")
                    for tt in range(k):
                        out.append(f"B {k + 1 - tt + SHIFT} {k - tt + SHIFT}")
                else:
                    k = B // 2
                    out.append(f"B {SHIFT - 1} {SHIFT}")
                    for j in range(k):
                        out.append(f"B {j + SHIFT} {j + 1 + SHIFT}")
                    for tt in range(k - 1):
                        out.append(f"B {k - tt + SHIFT} {k - 1 - tt + SHIFT}")

            out.append(f"R {SHIFT + 1} {SHIFT}")  # C

            # Remaining red vertices of the rectangle cycle.
            w = R // 2 - 1
            for col in range(-1, -w - 1, -1):
                out.append(f"R {SHIFT + 1} {col + SHIFT}")
            for col in range(-w, 0):
                out.append(f"R {SHIFT} {col + SHIFT}")

    sys.stdout.write("\n".join(out))

