import sys

def main():
    s = sys.stdin.buffer.readline().strip()
    n = len(s)
    if n == 0:
        return

    r = s[::-1]

    # Prefix function for the reversed string r
    pi = [0] * n
    for i in range(1, n):
        j = pi[i - 1]
        c = r[i]
        while j and c != r[j]:
            j = pi[j - 1]
        if c == r[j]:
            j += 1
        pi[i] = j

    # KMP scan: longest prefix of r that is a suffix of s
    j = 0
    for c in s:
        while j and c != r[j]:
            j = pi[j - 1]
        if c == r[j]:
            j += 1
            if j == n:
                break

    # Append the reverse of the prefix before the longest palindromic suffix
    ans = s + s[:n - j][::-1]
    sys.stdout.buffer.write(ans + b"\n")

if __name__ == "__main__":
    main()

