FACTORS[2] = (1, 0, 0, 0)
FACTORS[3] = (0, 1, 0, 0)
FACTORS[4] = (2, 0, 0, 0)
FACTORS[5] = (0, 0, 1, 0)
FACTORS[6] = (1, 1, 0, 0)
FACTORS[7] = (0, 0, 0, 1)
FACTORS[8] = (3, 0, 0, 0)
FACTORS[9] = (0, 2, 0, 0)


@lru_cache(maxsize=None)
def _free(rem, sm, e2, e3, e5, e7):
    if sm > MAX_SUM or sm + rem > MAX_SUM:
        return 0

    if rem == 0:
        req = REQ[sm]
        if req is None:
            return 0
        return 1 if e2 >= req[0] and e3 >= req[1] and e5 >= req[2] and e7 >= req[3] else 0

    total = 0
    c2, c3, c5, c7 = CAPS

    for d in range(1, 10):
        ns = sm + d
        if ns > MAX_SUM:
            continue

        f = FACTORS[d]

        ne2 = e2 + f[0]
        if ne2 > c2:
            ne2 = c2
        ne3 = e3 + f[1]
        if ne3 > c3:
            ne3 = c3
        ne5 = e5 + f[2]
        if ne5 > c5:
            ne5 = c5
        ne7 = e7 + f[3]
        if ne7 > c7:
            ne7 = c7

        total += _free(rem - 1, ns, ne2, ne3, ne5, ne7)

    return total


EXACT_LEN = [0] * (MAX_LEN + 1)
for length in range(1, MAX_LEN):
    total = 0
    c2, c3, c5, c7 = CAPS
    for d in range(1, 10):
        f = FACTORS[d]
        ne2 = f[0] if f[0] < c2 else c2
        ne3 = f[1] if f[1] < c3 else c3
        ne5 = f[2] if f[2] < c5 else c5
        ne7 = f[3] if f[3] < c7 else c7
        total += _free(length - 1, d, ne2, ne3, ne5, ne7)
    EXACT_LEN[length] = total

EXACT_PREFIX = [0] * (MAX_LEN + 1)
for i in range(1, MAX_LEN + 1):
    EXACT_PREFIX[i] = EXACT_PREFIX[i - 1] + EXACT_LEN[i]


class Solution:
    def beautifulNumbers(self, l: int, r: int) -> int:
        return self._count(r) - self._count(l - 1)

    def _count(self, n: int) -> int:
        if n <= 0:
            return 0
        return n - self._count_no_zero(n) + self._count_beautiful_no_zero(n)

    def _count_no_zero(self, n: int) -> int:
        s = str(n)
        length = len(s)

        pow9 = [1] * (length + 1)
        for i in range(1, length + 1):
            pow9[i] = pow9[i - 1] * 9

        ans = 0
        for ln in range(1, length):
            ans += pow9[ln]

        for i, ch in enumerate(s):
            d = ord(ch) - 48
            rem = length - i - 1

            if d > 1:
                ans += (d - 1) * pow9[rem]

            if d == 0:
                return ans

        return ans + 1

    def _count_beautiful_no_zero(self, n: int) -> int:
        if n <= 0:
            return 0

        s = str(n)
        length = len(s)

        if length > MAX_LEN:
            return self._count_beautiful_no_zero_fallback(n)

        ans = EXACT_PREFIX[length - 1]

        sm = 0
        e2 = e3 = e5 = e7 = 0
        c2, c3, c5, c7 = CAPS

        for i, ch in enumerate(s):
            d = ord(ch) - 48
            rem = length - i - 1

            for c in range(1, d):
                ns = sm + c
                if ns > MAX_SUM:
                    continue

                f = FACTORS[c]

                ne2 = e2 + f[0]
                if ne2 > c2:
                    ne2 = c2
                ne3 = e3 + f[1]
                if ne3 > c3:
                    ne3 = c3
                ne5 = e5 + f[2]
                if ne5 > c5:
                    ne5 = c5
                ne7 = e7 + f[3]
                if ne7 > c7:
                    ne7 = c7

                ans += _free(rem, ns, ne2, ne3, ne5, ne7)

            if d == 0:
                return ans

            f = FACTORS[d]
            sm += d

            e2 += f[0]
            if e2 > c2:
                e2 = c2
            e3 += f[1]
            if e3 > c3:
                e3 = c3
            e5 += f[2]
            if e5 > c5:
                e5 = c5
            e7 += f[3]
            if e7 > c7:
                e7 = c7

        req = REQ[sm] if sm <= MAX_SUM else None
        if req is not None and e2 >= req[0] and e3 >= req[1] and e5 >= req[2] and e7 >= req[3]:
            ans += 1

        return ans

    def _count_beautiful_no_zero_fallback(self, n: int) -> int:
        digits = [ord(ch) - 48 for ch in str(n)]
        max_sum = 9 * len(digits)

        req = [None] * (max_sum + 1)
        caps = [0, 0, 0, 0]

        for s in range(1, max_sum + 1):
            t = s
            e = [0, 0, 0, 0]
            for i, p in enumerate(PRIMES):
                while t % p == 0:
                    t //= p
                    e[i] += 1
            if t == 1:
                req[s] = (e[0], e[1], e[2], e[3])
                for i in range(4):
                    if e[i] > caps[i]:
                        caps[i] = e[i]

        caps = tuple(caps)
        c2, c3, c5, c7 = caps

        @lru_cache(maxsize=None)
        def dfs(pos, tight, started, sm, e2, e3, e5, e7):
            if pos == len(digits):
                if not started:
                    return 0
                if sm > max_sum:
                    return 0
                r = req[sm]
                if r is None:
                    return 0
                return 1 if e2 >= r[0] and e3 >= r[1] and e5 >= r[2] and e7 >= r[3] else 0

            limit = digits[pos] if tight else 9
            total = 0

            for d in range(limit + 1):
                ntight = tight and (d == digits[pos])

                if not started and d == 0:
                    total += dfs(pos + 1, ntight, False, 0, 0, 0, 0, 0)
                else:
                    if d == 0:
                        continue

                    ns = sm + d
                    if ns > max_sum:
                        continue

                    f = FACTORS[d]

                    ne2 = e2 + f[0]
                    if ne2 > c2:
                        ne2 = c2
                    ne3 = e3 + f[1]
                    if ne3 > c3:
                        ne3 = c3
                    ne5 = e5 + f[2]
                    if ne5 > c5:
                        ne5 = c5
                    ne7 = e7 + f[3]
                    if ne7 > c7:
                        ne7 = c7

                    total += dfs(pos + 1, ntight, True, ns, ne2, ne3, ne5, ne7)

            return total

        return dfs(0, True, False, 0, 0, 0, 0, 0)

import sys
from collections import deque


class Edge:
    __slots__ = ("to", "rev", "cap")

    def __init__(self, to, rev, cap):
        self.to = to
        self.rev = rev
        self.cap = cap


class Dinic:
    def __init__(self, n):
        self.n = n
        self.g = [[] for _ in range(n)]
        self.level = []
        self.it = []

    def add_edge(self, fr, to, cap):
        if fr == to:
            return
        f = Edge(to, len(self.g[to]), cap)
        r = Edge(fr, len(self.g[fr]), 0)
        self.g[fr].append(f)
        self.g[to].append(r)

    def bfs(self, s, t):
        level = [-1] * self.n
        level[s] = 0
        q = deque([s])
        while q:
            v = q.popleft()
            for e in self.g[v]:
                if e.cap > 0 and level[e.to] < 0:
                    level[e.to] = level[v] + 1
                    q.append(e.to)
        self.level = level
        return level[t] >= 0

    def dfs(self, v, t, f):
        if v == t:
            return f
        while self.it[v] < len(self.g[v]):
            e = self.g[v][self.it[v]]
            if e.cap > 0 and self.level[e.to] == self.level[v] + 1:
                ret = self.dfs(e.to, t, f if f < e.cap else e.cap)
                if ret:
                    e.cap -= ret
                    self.g[e.to][e.rev].cap += ret
                    return ret
            self.it[v] += 1
        return 0

    def max_flow(self, s, t, limit):
        flow = 0
        while flow < limit and self.bfs(s, t):
            self.it = [0] * self.n
            while flow < limit:
                f = self.dfs(s, t, limit - flow)
                if f == 0:
                    break
                flow += f
        return flow


def solve():
    sys.setrecursionlimit(1_000_000)
    input = sys.stdin.buffer.readline

    N, M, K = map(int, input().split())
    edges = []
    adj = [[] for _ in range(N)]

    for _ in range(M):
        u, v = map(int, input().split())
        u -= 1
        v -= 1
        edges.append((u, v))
        adj[u].append(v)

    # Unweighted shortest path length is an upper bound.
    dist = [-1] * N
    dist[0] = 0
    q = deque([0])
    while q:
        v = q.popleft()
        for to in adj[v]:
            if dist[to] < 0:
                dist[to] = dist[v] + 1
                q.append(to)

    L = dist[N - 1]
    if L < 0:
        print(0)
        return

    INF = 10**9

    def feasible(d):
        if d == 0:
            return True

        total = 2 + N * d
        SRC, SNK = 0, 1
        dinic = Dinic(total)

        # Fixed labels and nested constraints.
        for v in range(N):
            base = 2 + v * d
            for i in range(1, d + 1):
                node = base + (i - 1)

                # source vertex must have label 0
                if v == 0:
                    dinic.add_edge(node, SNK, INF)

                # sink vertex must have label d
                if v == N - 1:
                    dinic.add_edge(SRC, node, INF)

                # label >= i implies label >= i-1
                if i > 1:
                    dinic.add_edge(node, base + (i - 2), INF)

        # Original edges.
        for u, v in edges:
            base_u = 2 + u * d
            base_v = 2 + v * d
            for i in range(1, d + 1):
                node_v = base_v + (i - 1)
                node_u = base_u + (i - 1)

                # Cost 1 if label(v) >= i and label(u) < i.
                dinic.add_edge(node_v, node_u, 1)

                # label(v) >= i implies label(u) >= i-1.
                if i > 1:
                    dinic.add_edge(node_v, base_u + (i - 2), INF)

        flow = dinic.max_flow(SRC, SNK, K + 1)
        return flow <= K

    lo, hi = 0, min(L, K) + 1
    while hi - lo > 1:
        mid = (lo + hi) // 2
        if feasible(mid):
            lo = mid
        else:
            hi = mid

    print(lo)


if __name__ == "__main__":
    solve()

import sys

def solve() -> None:
    data = sys.stdin.read().split()
    if not data:
        return

    N = int(data[0])
    X = int(data[1])
    Y = int(data[2])
    S = data[3]
    T = data[4]

    # The number of 1s (and hence 0s) is invariant.
    if S.count('1') != T.count('1'):
        print("No")
        return

    # For every k, the position of the k-th 1 modulo X is invariant.
    if X != 1:
        seq = []
        for i, ch in enumerate(S):
            if ch == '1':
                seq.append(i % X)

        idx = 0
        ok = True
        for i, ch in enumerate(T):
            if ch == '1':
                if idx >= len(seq) or seq[idx] != i % X:
                    ok = False
                    break
                idx += 1

        if not ok or idx != len(seq):
            print("No")
            return

    # For every k, the position of the k-th 0 modulo Y is invariant.
    if Y != 1:
        seq = []
        for i, ch in enumerate(S):
            if ch == '0':
                seq.append(i % Y)

        idx = 0
        ok = True
        for i, ch in enumerate(T):
            if ch == '0':
                if idx >= len(seq) or seq[idx] != i % Y:
                    ok = False
                    break
                idx += 1

        if not ok or idx != len(seq):
            print("No")
            return

    print("Yes")

