    solve()

from typing import List

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        m = len(conflictingPairs)
        buckets = [[] for _ in range(n + 1)]

        for i, (a, b) in enumerate(conflictingPairs):
            if a > b:
                a, b = b, a
            buckets[b].append((a, i))

        gain = [0] * m

        top1 = 0          # maximum left endpoint among active pairs
        top2 = 0          # second maximum distinct left endpoint
        cnt1 = 0          # number of active pairs having left endpoint == top1
        top_id = -1       # id of the unique pair with left endpoint == top1

        base = 0

        for r in range(1, n + 1):
            for a, idx in buckets[r]:
                if a > top1:
                    top2 = top1
                    top1 = a
                    cnt1 = 1
                    top_id = idx
                elif a == top1:
                    cnt1 += 1
                    if cnt1 == 2:
                        top_id = -1
                else:
                    if a > top2:
                        top2 = a

            base += r - top1

            if cnt1 == 1:
                gain[top_id] += top1 - top2

        return base + (max(gain) if gain else 0)

from typing import List

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        if k <= 0:
            return []

        # Any count >= limit is equivalent to "large enough" for the current k.
        limit = k + 1

        def cap_mul(a: int, b: int) -> int:
            if a == 0 or b == 0:
                return 0
            if a > limit // b:
                return limit
            return a * b

        # factorials capped at limit
        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = cap_mul(fact[i - 1], i)

        def count(ro: int, re: int, last: int) -> int:
            """
            Number of valid completions with:
            - ro remaining odd numbers
            - re remaining even numbers
            - last parity: 1 = odd, 0 = even, -1 = no previous element
            """
            if ro < 0 or re < 0:
                return 0

            m = ro + re
            if m == 0:
                return 1

            if last == -1:
                if ro == re:
                    return cap_mul(2, cap_mul(fact[ro], fact[re]))
                if ro == re + 1 or re == ro + 1:
                    return cap_mul(fact[ro], fact[re])
                return 0

            # Next parity is forced.
            next_p = 1 - last
            need_next = (m + 1) // 2
            need_other = m // 2

            if next_p == 1:
                if ro == need_next and re == need_other:
                    return cap_mul(fact[ro], fact[re])
            else:
                if re == need_next and ro == need_other:
                    return cap_mul(fact[ro], fact[re])

            return 0

        odd = (n + 1) // 2
        even = n // 2

        used = [False] * (n + 1)
        ans = []
        last = -1

        for _ in range(n):
            chosen = -1

            for x in range(1, n + 1):
                if used[x]:
                    continue

                p = x & 1

                # Adjacent parities must differ.
                if last != -1 and p == last:
                    continue

                if p == 1:
                    cnt = count(odd - 1, even, 1)
                else:
                    cnt = count(odd, even - 1, 0)

                if k > cnt:
                    k -= cnt
                else:
                    chosen = x
                    break

            if chosen == -1:
                return []

            ans.append(chosen)
            used[chosen] = True

            if chosen & 1:
                odd -= 1
            else:
                even -= 1

            last = chosen & 1

        return ans

from typing import List
import heapq
from bisect import bisect_left


class Solution:
    def maxDistance(self, side: int, points: List[List[int]], k: int) -> int:
        if k <= 1:
            return 0

        s = side
        two_s = 2 * s

        # Map the square boundary to two monotone chains in (u, v) space:
        # u = x + y, v = x - y.  Manhattan distance becomes Chebyshev distance.
        # Upper chain: bottom + right, lower chain: left + top.
        # For same chain, distance = |u1 - u2|.
        # For different chains, distance = max(|u1 - u2|, h1 + h2),
        # where h = min(u, 2*s - u).
        arr = []
        for x, y in points:
            if y == 0 or x == s:
                c = 0
                if y == 0:
                    u = x
                else:
                    u = s + y
            else:
                c = 1
                if x == 0:
                    u = y
                else:
                    u = s + x

            h = u if u <= two_s - u else two_s - u
            arr.append((u, c, h))

        arr.sort(key=lambda z: (z[0], z[1]))
        n = len(arr)

        U = [a[0] for a in arr]
        C = [a[1] for a in arr]
        H = [a[2] for a in arr]

        h_vals = sorted(set(H))
        m_h = len(h_vals)
        h_idx = [bisect_left(h_vals, h) for h in H]
        min_h = h_vals[0]
        max_h = h_vals[-1]

        INF = 10**30
        NEG = -10**30

        def check(D: int) -> bool:
            if D == 0:
                return True
            if D > two_s:
                return False

            # Each chain can contain at most floor(2*s / D) + 1 selected points.
            if 2 * (two_s // D + 1) < k:
                return False

            U_loc = U
            C_loc = C
            H_loc = H
            h_idx_loc = h_idx
            n_loc = n
            k_loc = k
            INF_loc = INF
            NEG_loc = NEG
            h_vals_loc = h_vals
            m_h_loc = m_h
            min_h_loc = min_h
            max_h_loc = max_h
            bisect_left_loc = bisect_left
            heappush = heapq.heappush
            heappop = heapq.heappop

            # Build DP for sequences of length 2.
            # dp[i] = minimum possible u-coordinate of the last selected point
            # on the opposite chain, for a valid sequence ending at point i.
            dp = [INF_loc] * n_loc
            bit0 = [INF_loc] * (m_h_loc + 1)
            bit1 = [INF_loc] * (m_h_loc + 1)

            first0 = INF_loc
            first1 = INF_loc
            any_valid = False

            for i in range(n_loc):
                ui = U_loc[i]
                T = ui - D
                c = C_loc[i]
                best = INF_loc

                if c == 0:
                    if first0 <= T:
                        best = NEG_loc
                    elif first1 <= T:
                        best = first1
                    elif first1 != INF_loc:
                        req = D - H_loc[i]
                        if req <= min_h_loc:
                            best = first1
                        elif req <= max_h_loc:
                            l = bisect_left_loc(h_vals_loc, req)
                            if l < m_h_loc:
                                idx = m_h_loc - l
                                res = INF_loc
                                bit = bit1
                                while idx:
                                    bv = bit[idx]
                                    if bv < res:
                                        res = bv
                                    idx -= idx & -idx
                                if res < best:
                                    best = res
                else:
                    if first1 <= T:
                        best = NEG_loc
                    elif first0 <= T:
                        best = first0
                    elif first0 != INF_loc:
                        req = D - H_loc[i]
                        if req <= min_h_loc:
                            best = first0
                        elif req <= max_h_loc:
                            l = bisect_left_loc(h_vals_loc, req)
                            if l < m_h_loc:
                                idx = m_h_loc - l
                                res = INF_loc
                                bit = bit0
                                while idx:
                                    bv = bit[idx]
                                    if bv < res:
                                        res = bv
                                    idx -= idx & -idx
                                if res < best:
                                    best = res

                dp[i] = best
                if best != INF_loc:
                    any_valid = True
                    if k_loc == 2:
                        return True

                # Insert current point as a possible previous point for later.
                hi = h_idx_loc[i]
                if c == 0:
                    if first0 == INF_loc:
                        first0 = ui
                    idx = m_h_loc - hi
                    while idx <= m_h_loc:
                        if ui < bit0[idx]:
                            bit0[idx] = ui
                            idx += idx & -idx
                        else:
                            break
                else:
                    if first1 == INF_loc:
                        first1 = ui
                    idx = m_h_loc - hi
                    while idx <= m_h_loc:
                        if ui < bit1[idx]:
                            bit1[idx] = ui
                            idx += idx & -idx
                        else:
                            break

            if not any_valid:
                return False
            if k_loc == 2:
                return True

            dp_prev = dp

            # Extend from length 2 up to k.
            for length in range(2, k_loc):
                # First valid point of each chain for the previous length.
                F0 = INF_loc
                F1 = INF_loc
                for i in range(n_loc):
                    if dp_prev[i] != INF_loc:
                        if C_loc[i] == 0:
                            if F0 == INF_loc:
                                F0 = U_loc[i]
                        else:
                            if F1 == INF_loc:
                                F1 = U_loc[i]
                        if F0 != INF_loc and F1 != INF_loc:
                            break

                if F0 == INF_loc and F1 == INF_loc:
                    return False

                dp_next = [INF_loc] * n_loc

                bit0 = [INF_loc] * (m_h_loc + 1)
                bit1 = [INF_loc] * (m_h_loc + 1)
                heap0 = []
                heap1 = []

                need0 = F0 != INF_loc
                need1 = F1 != INF_loc

                pref0 = INF_loc
                pref1 = INF_loc
                all0 = INF_loc
                all1 = INF_loc

                p = 0
                any_valid = False
                target_len = length + 1

                for i in range(n_loc):
                    ui = U_loc[i]
                    T = ui - D

                    if need0 and F0 <= T:
                        need0 = False
                    if need1 and F1 <= T:
                        need1 = False

                    # Same-chain prefix transitions.
                    while p < i and U_loc[p] <= T:
                        val = dp_prev[p]
                        if val != INF_loc:
                            if C_loc[p] == 0:
                                if val < pref0:
                                    pref0 = val
                            else:
                                if val < pref1:
                                    pref1 = val
                        p += 1

                    # If a same-chain prefix exists, recent opposite transitions
                    # can never give a smaller last-other coordinate.
                    if pref1 != INF_loc:
                        need0 = False
                    if pref0 != INF_loc:
                        need1 = False

                    # Make point i-1 available as a previous last point.
                    if i:
                        j = i - 1
                        val = dp_prev[j]
                        if val != INF_loc:
                            if C_loc[j] == 0:
                                if need0 and val < F0:
                                    heappush(heap0, (val, U_loc[j], h_idx_loc[j]))
                            else:
                                if need1 and val < F1:
                                    heappush(heap1, (val, U_loc[j], h_idx_loc[j]))

                    # Activate recent opposite points whose last-other is far enough.
                    if need0 and heap0:
                        while heap0 and heap0[0][0] <= T:
                            _, uj, hj = heappop(heap0)
                            if uj < all0:
                                all0 = uj
                            idx = m_h_loc - hj
                            while idx <= m_h_loc:
                                if uj < bit0[idx]:
                                    bit0[idx] = uj
                                    idx += idx & -idx
                                else:
                                    break

                    if need1 and heap1:
                        while heap1 and heap1[0][0] <= T:
                            _, uj, hj = heappop(heap1)
                            if uj < all1:
                                all1 = uj
                            idx = m_h_loc - hj
                            while idx <= m_h_loc:
                                if uj < bit1[idx]:
                                    bit1[idx] = uj
                                    idx += idx & -idx
                                else:
                                    break

                    c = C_loc[i]

                    if c == 0:
                        best = pref0

