                            req = D - H_loc[i]
                            if req <= min_h_loc:
                                res = all1
                            elif req <= max_h_loc:
                                l = bisect_left_loc(h_vals_loc, req)
                                if l < m_h_loc:
                                    idx = m_h_loc - l
                                    res = INF_loc
                                    bit = bit1
                                    while idx:
                                        bv = bit[idx]
                                        if bv < res:
                                            res = bv
                                        idx -= idx & -idx
                                else:
                                    res = INF_loc
                            else:
                                res = INF_loc

                            if res < best:
                                best = res
                    else:
                        best = pref1

