                                    res = INF_loc
                                    bit = bit0
                                    while idx:
                                        bv = bit[idx]
                                        if bv < res:
                                            res = bv
                                        idx -= idx & -idx
                                else:
                                    res = INF_loc
                            else:
                                res = INF_loc

                            if res < best:
                                best = res

                    dp_next[i] = best
                    if best != INF_loc:
                        any_valid = True
                        if target_len == k_loc:
