import sys


def solve():
    input = sys.stdin.buffer.readline

    H, W = map(int, input().split())
    N = H * W

    val = [0] * (N + 1)
    idx = 1
    for _ in range(H):
        for x in map(int, input().split()):
            val[idx] = x
            idx += 1

    Q = int(input())

    # sets[root] = set of query ids having exactly one endpoint in this DSU component
    sets = [None] * (N + 1)

    ans = [-1] * Q
    low = [0] * Q       # min(Y, Z)
    diff = [0] * Q      # abs(Y - Z)
    total = [0] * Q     # Y + Z

    remaining = 0

    for qi in range(Q):
        A, B, Y, C, D, Z = map(int, input().split())

        if Y < Z:
            low[qi] = Y
            diff[qi] = Z - Y
        else:
            low[qi] = Z
            diff[qi] = Y - Z
        total[qi] = Y + Z

        u = (A - 1) * W + B
        v = (C - 1) * W + D

        if u == v:
            ans[qi] = diff[qi]
        else:
            remaining += 1

            s = sets[u]
            if s is None:
                sets[u] = {qi}
            else:
                s.add(qi)

            s = sets[v]
            if s is None:
                sets[v] = {qi}
            else:
                s.add(qi)

    if remaining == 0:
        sys.stdout.write("\n".join(map(str, ans)))
        return

    # Pack edges into integers: (weight, u, v), sorted descending by weight.
    SHIFT = 20
    MASK = (1 << SHIFT) - 1

    edges = []
    append = edges.append
    vlist = val

    if W > 1:
        for r in range(H):
            start = r * W + 1
            end = start + W - 1
            for u in range(start, end):
                v = u + 1
                w = vlist[u]
                if vlist[v] < w:
                    w = vlist[v]
                append((w << 40) | (u << SHIFT) | v)

    if H > 1:
        limit = N - W
        for u in range(1, limit + 1):
            v = u + W
            w = vlist[u]
            if vlist[v] < w:
                w = vlist[v]
            append((w << 40) | (u << SHIFT) | v)

    del val, vlist

    edges.sort(reverse=True)

    parent = list(range(N + 1))
    size = [1] * (N + 1)

    def find(x, parent=parent):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    sets_l = sets
    ans_l = ans
    low_l = low
    diff_l = diff
    total_l = total
    find_l = find
    parent_l = parent
    size_l = size

    SMALL = 8

    for e in edges:
        w = e >> 40
        u = (e >> SHIFT) & MASK
        v = e & MASK

        ru = find_l(u)
        rv = find_l(v)
        if ru == rv:
            continue

        if size_l[ru] < size_l[rv]:
            ru, rv = rv, ru

        parent_l[rv] = ru
        size_l[ru] += size_l[rv]

        su = sets_l[ru]
        sv = sets_l[rv]

        if su is None:
            sets_l[ru] = sv if sv else None
        elif sv is not None:
            if su is sv:
                sets_l[ru] = su if su else None
            else:
                if len(su) < len(sv):
                    su, sv = sv, su

                if len(sv) <= SMALL:
                    for qid in sv:
                        if qid in su:
                            if ans_l[qid] == -1:
                                if w >= low_l[qid]:
                                    ans_l[qid] = diff_l[qid]
                                else:
                                    ans_l[qid] = total_l[qid] - 2 * w
                                remaining -= 1
                                if remaining == 0:
                                    break
                            su.remove(qid)
                        else:
                            su.add(qid)

                    sets_l[ru] = su if su else None
                else:
                    common = su.intersection(sv)

                    for qid in common:
                        if ans_l[qid] == -1:
                            if w >= low_l[qid]:
                                ans_l[qid] = diff_l[qid]
                            else:
                                ans_l[qid] = total_l[qid] - 2 * w
                            remaining -= 1
                            if remaining == 0:
                                break

                    if remaining == 0:
                        break

                    su.difference_update(common)
                    sv.difference_update(common)
                    su.update(sv)

                    sets_l[ru] = su if su else None

        sets_l[rv] = None

        if remaining == 0:
            break

    # Safety fallback; with correct processing this should never be needed.
    for i in range(Q):
        if ans[i] == -1:
            ans[i] = diff[i]

    sys.stdout.write("\n".join(map(str, ans)))


