class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        from bisect import bisect_left, bisect_right

        def kmp_occurrences(text: str, pat: str):
            n = len(text)
            m = len(pat)
            if m == 0:
                return list(range(n + 1))
            if m > n:
                return []

            pi = [0] * m
            for i in range(1, m):
                j = pi[i - 1]
                while j > 0 and pat[i] != pat[j]:
                    j = pi[j - 1]
                if pat[i] == pat[j]:
                    j += 1
                pi[i] = j

            occ = []
            j = 0
            for i, ch in enumerate(text):
                while j > 0 and ch != pat[j]:
                    j = pi[j - 1]
                if ch == pat[j]:
                    j += 1
                    if j == m:
                        occ.append(i - m + 1)
                        j = pi[j - 1]
            return occ

        A, B, C = p.split('*')

        # Keep only non-empty literal parts. Stars only allow gaps between them.
        parts = []
        for part in (A, B, C):
            if part:
                occ = kmp_occurrences(s, part)
                if not occ:
                    return -1
                parts.append((len(part), occ))

        if not parts:
            return 0

        if len(parts) == 1:
            return parts[0][0]

        INF = 10**18

        if len(parts) == 2:
            (l1, occ1), (l2, occ2) = parts
            ans = INF

            for k in occ2:
                idx = bisect_right(occ1, k - l1) - 1
                if idx >= 0:
                    cur = k + l2 - occ1[idx]
                    if cur < ans:
                        ans = cur

            return -1 if ans == INF else ans

        if len(parts) == 3:
            (l1, occ1), (l2, occ2), (l3, occ3) = parts
            ans = INF

            for j in occ2:
                i_idx = bisect_right(occ1, j - l1) - 1
                if i_idx < 0:
                    continue

                k_idx = bisect_left(occ3, j + l2)
                if k_idx < len(occ3):
                    cur = occ3[k_idx] + l3 - occ1[i_idx]
                    if cur < ans:
                        ans = cur

            return -1 if ans == INF else ans

        return -1

