from math import gcd, isqrt


def main():
    tokens = sys.stdin.buffer.read().split()
    if not tokens:
        return

    it = iter(tokens)
    N = int(next(it))
    K = int(next(it))
    A = list(map(int, it))
    del tokens, it

    write = sys.stdout.write
    chunk = 200000
    str_ = str

    if K == 1:
        for i in range(0, N, chunk):
            write("\n".join([str_(x) for x in A[i:i + chunk]]))
            write("\n")
        return

    if K == N:
        g = 0
        for x in A:
            g = gcd(g, x)
            if g == 1:
                break
        write((str_(g) + "\n") * N)
        return

    M = max(A)

    # For small N and large values, enumerating divisors is faster.
    if N <= 5000 and M > 500000:
        freq = {}
        for x in A:
            freq[x] = freq.get(x, 0) + 1

        cnt = [0] * (M + 1)
        k = K
        divs = {}
        isqrt_ = isqrt

        for v, f in freq.items():
            ds = []
            r = isqrt_(v)
            for d in range(1, r + 1):
                if v % d == 0:
                    ds.append(d)
                    q = v // d
                    if q != d:
                        ds.append(q)
            divs[v] = ds

            if f > k:
                f = k
            for d in ds:
                if cnt[d] < k:
                    nv = cnt[d] + f
                    cnt[d] = k if nv >= k else nv

        ans = {}
        for v, ds in divs.items():
            best = 1
            for d in ds:
                if cnt[d] >= k and d > best:
                    best = d
            ans[v] = best

        for i in range(0, N, chunk):
            write("\n".join([str_(ans[x]) for x in A[i:i + chunk]]))
            write("\n")
        return

    cnt = [0] * (M + 1)
    c = cnt
    k = K
    EARLY_LIMIT = 2000

    # Frequency, capped at K when K is small.
    if k <= EARLY_LIMIT:
        for x in A:
            v = c[x]
            if v < k:
                c[x] = v + 1
    else:
        for x in A:
            c[x] += 1

    half = M >> 1
    M1 = M + 1

    # Count multiples.  For small K, stop once the count reaches K.
    if k <= EARLY_LIMIT:
        for d in range(1, half + 1):
            s = 0
            for m in range(d, M1, d):
                s += c[m]
                if s >= k:
                    s = k
                    break
            c[d] = s
    else:
        for d in range(1, half + 1):
            s = 0
            for m in range(d, M1, d):
                s += c[m]
            c[d] = s

    # Reuse cnt as the answer array.
    # Process possible gcds in descending order; the first good divisor
    # assigned to a multiple is its maximum possible gcd.
    for d in range(M, half, -1):
        if c[d] >= k:
            c[d] = d
        else:
            c[d] = 0

    for d in range(half, 0, -1):
        if c[d] >= k:
            c[d] = d
            for m in range(d + d, M1, d):
                if not c[m]:
                    c[m] = d
        else:
            c[d] = 0

    for i in range(0, N, chunk):
        write("\n".join([str_(c[x]) for x in A[i:i + chunk]]))
        write("\n")


