class Solution:
    def maxScore(self, points: List[int], m: int) -> int:
        n = len(points)

        # Not needed for the given constraints (n >= 2), but keeps the logic complete.
        if n == 1:
            return points[0] if m >= 1 else 0

        max_p = max(points)
        lo, hi = 0, max_p * m

        def can(score: int, pts=points, mm=m, nn=n) -> bool:
            if score == 0:
                return True
            if mm == 0:
                return False

            # First move is forced: -1 -> 0
            moves = 1
            cur = pts[0]   # current score at index i
            nxt = 0        # accumulated score at index i + 1

            for i in range(nn - 1):
                # Make index i reach the target by bouncing with i + 1.
                if cur < score:
                    p = pts[i]
                    need = (score - cur + p - 1) // p
                    if moves + need * 2 > mm:
                        return False
                    moves += need * 2
                    nxt += need * pts[i + 1]

                # Last edge: decide whether to stop at n-2 or go to n-1.
                if i == nn - 2:
                    if nxt < score:
                        # Must visit the last index at least once.
                        if moves + 1 > mm:
                            return False
                        moves += 1
                        nxt += pts[i + 1]

                        # If still insufficient, bounce between n-2 and n-1.
                        if nxt < score:
                            p_last = pts[i + 1]
                            need = (score - nxt + p_last - 1) // p_last
                            if moves + need * 2 > mm:
                                return False
                            moves += need * 2
                    return True

                # Move right to continue processing.
                if moves + 1 > mm:
                    return False
                moves += 1
                nxt += pts[i + 1]
                cur = nxt
                nxt = 0

            return cur >= score

        while lo < hi:
            mid = (lo + hi + 1) // 2
            if can(mid):
                lo = mid
            else:
                hi = mid - 1

        return lo

