MOD = 998244353

def solve():
    data = sys.stdin.read().split()
    if not data:
        return

    N = int(data[0])
    M = int(data[1])
    S = data[2]
    s_codes = [ord(ch) - 97 for ch in S]

    size = 1 << N

    # popcount for each mask
    pop = [0] * size
    for mask in range(1, size):
        pop[mask] = pop[mask >> 1] + (mask & 1)

    # vals[mask][i] = LCS length of S[:i] and the prefix represented by mask
    vals = []
    for mask in range(size):
        arr = [0] * (N + 1)
        cnt = 0
        for i in range(1, N + 1):
            if mask & (1 << (i - 1)):
                cnt += 1
            arr[i] = cnt
        vals.append(arr)

    # Precompute transitions: for each state and character, next state.
    # Store as (next_state, number_of_characters) to reduce DP operations.
    trans = []
    for mask in range(size):
        v = vals[mask]
        d = {}
        for c in range(26):
            w_prev = 0
            nxt = 0
            for i in range(1, N + 1):
                best = v[i]
                if w_prev > best:
                    best = w_prev
                if s_codes[i - 1] == c:
                    cand = v[i - 1] + 1
                    if cand > best:
                        best = cand

                if best != w_prev:
                    nxt |= 1 << (i - 1)
                w_prev = best

            d[nxt] = d.get(nxt, 0) + 1
        trans.append(list(d.items()))

    dp = [0] * size
    dp[0] = 1

    for _ in range(M):
        ndp = [0] * size
        for mask, val in enumerate(dp):
            if val == 0:
                continue
            for nxt, cnt in trans[mask]:
                ndp[nxt] = (ndp[nxt] + val * cnt) % MOD
        dp = ndp

    ans = [0] * (N + 1)
    for mask, val in enumerate(dp):
        ans[pop[mask]] = (ans[pop[mask]] + val) % MOD

    print(" ".join(map(str, ans)))

