from typing import List

class Solution:
    def minMaxSubarraySum(self, nums: List[int], k: int) -> int:
        def count_pairs(a: int, b: int, k: int) -> int:
            # Count pairs (p, q) with 1 <= p <= a, 1 <= q <= b,
            # and p + q - 1 <= k, i.e. p + q <= k + 1.
            if k >= a + b - 1:
                return a * b

            m = a if a < k else k
            c = k + 1 - b
            if c < 0:
                c = 0
            elif c > m:
                c = m

            res = c * b
            if m > c:
                t = m - c
                res += t * (k + 1) - (c + 1 + m) * t // 2
            return res

        def sum_min(arr: List[int]) -> int:
            n = len(arr)

            # left[i] = previous index with value < arr[i]
            left = [-1] * n
            stack = []
            for i, x in enumerate(arr):
                while stack and arr[stack[-1]] >= x:
                    stack.pop()
                if stack:
                    left[i] = stack[-1]
                stack.append(i)

            total = 0
            stack.clear()

            # right[i] = next index with value <= arr[i]
            for i in range(n - 1, -1, -1):
                x = arr[i]
                while stack and arr[stack[-1]] > x:
                    stack.pop()

                right = stack[-1] if stack else n

                left_count = i - left[i]
                right_count = right - i

                total += count_pairs(left_count, right_count, k) * x
                stack.append(i)

            return total

        # Sum of maxima = - sum of minima of negated array.
        return sum_min(nums) - sum_min([-x for x in nums])

