def main():
    data = sys.stdin.buffer.read().split()
    if not data:
        return

    N = int(data[0])
    MOD = int(data[1])

    H = N // 2
    maxE = N * (N - 1) // 2
    minM = N - 1
    maxE1 = maxE + 1
    mod = MOD
    mod_minus_1 = mod - 1

    # Binomial coefficients modulo MOD, up to maxE.
    comb = [[0] * maxE1 for _ in range(maxE1)]
    for i in range(maxE1):
        comb[i][0] = 1
        comb[i][i] = 1
        if i >= 2:
            prev = comb[i - 1]
            row = comb[i]
            for j in range(1, i):
                row[j] = (prev[j - 1] + prev[j]) % mod

    tri = [i * (i - 1) // 2 for i in range(N + 1)]

    # maxadd[a][r][q][ae]:
    # maximum additional exponent possible when the previous layer has size a,
    # r vertices remain, the next layer parity is q (0 even, 1 odd),
    # and ae even vertices are still needed.
    NEG = -10**9
    maxadd = [[[[NEG] * (H + 1) for _ in range(2)] for _ in range(N + 1)] for _ in range(N + 1)]
    for a in range(1, N + 1):
        maxadd[a][0][0][0] = 0
        maxadd[a][0][1][0] = 0

    for r in range(1, N + 1):
        for q in range(2):
            for ae in range(H + 1):
                ao = r - ae
                if ao < 0 or ao > H:
                    continue
                for a in range(1, N + 1):
                    maxb = ae if q == 0 else ao
                    if maxb > r:
                        maxb = r
                    best = NEG
                    for b in range(1, maxb + 1):
                        nae = ae - b if q == 0 else ae
                        sub = maxadd[b][r - b][1 - q][nae]
                        if sub >= 0:
                            val = tri[b] + a * b + sub
                            if val > best:
                                best = val
                    maxadd[a][r][q][ae] = best

    # Valid transitions of layer sizes, with pruning by final balance and exponent.
    next_infos = [[[[] for _ in range(2)] for _ in range(H + 1)] for __ in range(N + 1)]
    for n in range(1, N):
        r = N - n
        for e in range(H + 1):
            odd = n - e
            if odd < 0 or odd > H:
                continue
            for p in range(2):
                q = p ^ 1
                lst = []
                maxb_even = H - e
                maxb_odd = H - odd
                for b in range(1, r + 1):
                    if q == 0:
                        if b > maxb_even:
                            continue
                        ne = e + b
                    else:
                        if b > maxb_odd:
                            continue
                        ne = e

                    r2 = r - b
                    ae2 = H - ne
                    if ae2 < 0 or ae2 > H:
                        continue

                    tmax = maxadd[b][r2][q ^ 1][ae2]
                    if tmax >= 0:
                        thresh = minM - tmax
                        tkey = (b << 5) | (ne << 1) | (q ^ 1)
                        lst.append((n + b, tkey, thresh, b))
                next_infos[n][e][p] = lst

    # Transition polynomials in the binomial basis:
    # C(N-n, b) * sum_j (-1)^j C(b,j) t^(C(b,2)+a(b-j)).
    terms = [[[None] * (N + 1) for _ in range(N + 1)] for __ in range(N + 1)]
    for n in range(1, N):
        rem = N - n
        for a in range(1, n + 1):
            for b in range(1, rem + 1):
                label = comb[rem][b]
                if label == 0:
                    continue
                base = tri[b]
                lst = []
                minsh = maxE1
                maxsh = -1
                for j in range(b + 1):
                    shift = base + a * (b - j)
                    if shift > maxE:
                        continue
                    coeff = (label * comb[b][j]) % mod
                    if j & 1:
                        if coeff:
                            coeff = mod - coeff
                    if coeff:
                        lst.append((shift, coeff))
                        if shift < minsh:
                            minsh = shift
                        if shift > maxsh:
                            maxsh = shift
                if lst:
                    terms[n][a][b] = (lst, minsh, maxsh)

    # DP over BFS layers.
    # State key: (last_layer_size << 5) | (even_count << 1) | current_parity
    # Value: dense array over exponent E.
    states = [{} for _ in range(N + 1)]
    root = [0] * maxE1
    root[0] = 1
    states[1][(1 << 5) | (1 << 1) | 0] = root

    bl = bisect_left
    br = bisect_right

    for n in range(1, N):
        cur = states[n]
        if not cur:
            continue

        infos_by_ep = next_infos[n]
        terms_n = terms[n]
        r = N - n

        for key, poly in cur.items():
            a = key >> 5
            e = (key >> 1) & 15
            p = key & 1

            if e > H:
                continue

            smax = maxadd[a][r][p ^ 1][H - e]
            if smax < 0:
                continue

            infos = infos_by_ep[e][p]
            if not infos:
                continue

            low = minM - smax
            if low < 0:
                low = 0
            if low > maxE:
                continue

            Es = []
            Vs = []
            appE = Es.append
            appV = Vs.append

            if low == 0:
                for E, v in enumerate(poly):
                    if v:
                        appE(E)
                        appV(v)
            else:
                for E in range(low, maxE1):
                    v = poly[E]
                    if v:
                        appE(E)
                        appV(v)

            if not Es:
                continue

            minE = Es[0]
            maxItemE = Es[-1]
            L = len(Es)
            terms_a = terms_n[a]

            for nb, tkey, thresh, b in infos:
                tinfo = terms_a[b]
                if tinfo is None:
                    continue

                lst, minsh, maxsh = tinfo
                if maxItemE + maxsh < thresh or minE + minsh > maxE:
                    continue

                sd = states[nb]
                target = sd.get(tkey)
                if target is None:
                    target = [0] * maxE1
                    sd[tkey] = target

                tgt = target

                for shift, coeff in lst:
                    lowE = thresh - shift
                    highE = maxE - shift

                    if lowE <= minE and highE >= maxItemE:
                        l = 0
                        rr = L
                    else:
                        if lowE > maxItemE or highE < minE:
                            continue
                        l = bl(Es, lowE)
                        rr = br(Es, highE)
                        if l >= rr:
                            continue

                    if coeff == 1:
                        for i in range(l, rr):
                            neE = Es[i] + shift
                            nv = tgt[neE] + Vs[i]
                            if nv >= mod:
                                nv -= mod
                            tgt[neE] = nv
                    elif coeff == mod_minus_1:
                        for i in range(l, rr):
                            neE = Es[i] + shift
                            nv = tgt[neE] + (mod - Vs[i])
                            if nv >= mod:
                                nv -= mod
                            tgt[neE] = nv
                    else:
                        for i in range(l, rr):
                            neE = Es[i] + shift
                            nv = tgt[neE] + (Vs[i] * coeff % mod)
                            if nv >= mod:
                                nv -= mod
                            tgt[neE] = nv

        states[n] = None

    # Collect A[E], the coefficient of t^E in the binomial-basis generating function.
    A = [0] * maxE1
    final = states[N]
    if final:
        for poly in final.values():
            for E in range(minM, maxE1):
                v = poly[E]
                if v:
                    nv = A[E] + v
                    if nv >= mod:
                        nv -= mod
                    A[E] = nv

    # Convert from sum A[E] (1+x)^E to coefficients of x^M.
    nz = [(E, A[E]) for E in range(minM, maxE1) if A[E]]
    ans = []
    for M in range(minM, maxE1):
        s = 0
        for E, ae in nz:
            if E >= M:
                s = (s + ae * comb[E][M]) % mod
        ans.append(str(s))

    sys.stdout.write(" ".join(ans) + "\n")


if __name__ == "__main__":
    main()

import sys
from math import isqrt
from bisect import bisect_right


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    N, M = data[0], data[1]
    P = data[2:]
    del data

    P.sort()
    p_min = P[0]

    if M < p_min:
        print(0)
        return

    # Upper bound for the marginal cost threshold.
    # For the cheapest product, buying q+1 units already costs more than M.
    q = isqrt(M // p_min)
    hi = (2 * q + 1) * p_min

    # Products whose first marginal cost is above hi can never be relevant.
    idx = bisect_right(P, hi)
    if idx < N:
        P = P[:idx]
    max_p = P[-1]

    def ok(C, P=P, max_p=max_p, M=M):
        total = 0
        if C >= max_p:
            for p in P:
                q = (C // p + 1) >> 1
                total += p * q * q
                if total > M:
                    return False
            return True
        else:
            for p in P:
                if p > C:
                    break
                q = (C // p + 1) >> 1
                total += p * q * q
                if total > M:
                    return False
            return True

    # Find the largest C such that all marginal costs <= C are affordable.
    lo = 0
    while hi - lo > 1:
        mid = (lo + hi) >> 1
        if ok(mid):
            lo = mid
        else:
            hi = mid

    cost = 0
    units = 0
    if lo >= max_p:
        for p in P:
            q = (lo // p + 1) >> 1
            cost += p * q * q
            units += q
    else:
        for p in P:
            if p > lo:
                break
            q = (lo // p + 1) >> 1
            cost += p * q * q
            units += q

    # The next marginal cost is lo + 1.
    ans = units + (M - cost) // (lo + 1)
    print(ans)


if __name__ == "__main__":
    main()

import sys

try:
    import numpy as np
    HAS_NP = True
except Exception:
    HAS_NP = False

_IS_PYPY = sys.implementation.name == "pypy"
_SPARSE_THRESHOLD = 1_000_000 if _IS_PYPY else 300_000

_big_params = {}


def get_big_params(n, mod):
    key = (n, mod)
    params = _big_params.get(key)
    if params is None:
        max_coeff = n * (mod - 1) * (mod - 1)
        b = max(1, max_coeff.bit_length() + 1)
        mask = (1 << b) - 1
        mid = b * (n - 1)
        params = (b, mask, mid)
        _big_params[key] = params
    return params


def matmul_big(A, B, mod):
    """Dense matrix multiplication using packed big integers."""
    n = len(A)
    b, mask, mid = get_big_params(n, mod)

    rows = []
    for row in A:
        x = 0
        for v in reversed(row):
            x = (x << b) | v
        rows.append(x)

    cols = []
    for col in zip(*B):
        x = 0
        for v in col:
            x = (x << b) | v
        cols.append(x)

    C = []
    for ri in rows:
        if ri == 0:
            C.append([0] * n)
        else:
            row = []
            for cj in cols:
                row.append((((ri * cj) >> mid) & mask) % mod)
            C.append(row)
    return C


def matmul_manual(A, B, mod):
    """Row-oriented multiplication, good for sparse A or small n."""
    n = len(A)
    C = []
    for i in range(n):
        Ci = [0] * n
        Ai = A[i]
        for k in range(n):
            a = Ai[k]
            if a:
                Bk = B[k]
                for j in range(n):
                    Ci[j] += a * Bk[j]
        for j in range(n):
            Ci[j] %= mod
        C.append(Ci)
    return C


def matmul_sparse_col(A, B, mod):
    """Column-oriented multiplication, good for sparse B."""
    n = len(A)

    nz_cols = [[] for _ in range(n)]
    for i in range(n):
        Bi = B[i]
        for j in range(n):
            bv = Bi[j]
            if bv:
                nz_cols[j].append((i, bv))

    A_cols = list(zip(*A))
    C_cols = [[0] * n for _ in range(n)]

    for j in range(n):
        Cj = C_cols[j]
        for i, bv in nz_cols[j]:
            colA = A_cols[i]
            for r in range(n):
                Cj[r] += colA[r] * bv

    C = [[0] * n for _ in range(n)]
    for j in range(n):
        Cj = C_cols[j]
        for i in range(n):
            C[i][j] = Cj[i] % mod
    return C


def matmul(A, B, mod):
    n = len(A)
    if n <= 30:
        return matmul_manual(A, B, mod)

    nnz_a = 0
    for row in A:
        for v in row:
            if v:
                nnz_a += 1

    nnz_b = 0
    for row in B:
        for v in row:
            if v:
                nnz_b += 1

    if min(nnz_a, nnz_b) * n <= _SPARSE_THRESHOLD:
        if nnz_a <= nnz_b:
            return matmul_manual(A, B, mod)
        else:
            return matmul_sparse_col(A, B, mod)

    return matmul_big(A, B, mod)


def mat_pow_py(A, exp, mod):
    n = len(A)
    result = None
    base = [row[:] for row in A]
    e = exp

    while e:
        if e & 1:
            if result is None:
                result = [row[:] for row in base]
            else:
                result = matmul(result, base, mod)
        e >>= 1
        if e:
            base = matmul(base, base, mod)

    if result is None:
        result = [[0] * n for _ in range(n)]
        for i in range(n):
            result[i][i] = 1 % mod
    return result


def matmul_np(A, B, mod):
    n = A.shape[0]
    C = np.zeros((n, n), dtype=np.int64)
    step = 8
    for k in range(0, n, step):
        k2 = min(n, k + step)
        C += A[:, k:k2] @ B[k:k2, :]
        C %= mod
    return C


def mat_pow_np(A, exp, mod):
    n = A.shape[0]
    result = None
    base = A.copy()
    e = exp

    while e:
        if e & 1:
            if result is None:
                result = base.copy()
            else:
                result = matmul_np(result, base, mod)
        e >>= 1
        if e:
            base = matmul_np(base, base, mod)

    if result is None:
        return np.eye(n, dtype=np.int64)
    return result


def matrix_power(A, exp, mod):
    n = len(A)

    if exp == 0:
        I = [[0] * n for _ in range(n)]
        for i in range(n):
            I[i][i] = 1 % mod
        return I

    zero = True
    diagonal = True
    for i in range(n):
        row = A[i]
        for j, v in enumerate(row):
            if v:
                zero = False
                if i != j:
                    diagonal = False

    if zero:
        return [[0] * n for _ in range(n)]

    if diagonal:
        res = [[0] * n for _ in range(n)]
        for i in range(n):
            res[i][i] = pow(A[i][i], exp, mod)
        return res

    if HAS_NP:
        arr = np.array(A, dtype=np.int64)
        return mat_pow_np(arr, exp, mod).tolist()

    return mat_pow_py(A, exp, mod)


def square_mod2(B):
    n = len(B)

    row_masks = []
    for row in B:
        m = 0
        for j, v in enumerate(row):
            if v:
                m |= 1 << j
        row_masks.append(m)

    col_masks = []
    for j in range(n):
        m = 0
        for i in range(n):
            if B[i][j]:
                m |= 1 << i
        col_masks.append(m)

    if hasattr(int, "bit_count"):
        def parity(x):
            return x.bit_count() & 1
    else:
        def parity(x):
            return bin(x).count("1") & 1

    return [[parity(row_masks[i] & col_masks[j]) for j in range(n)] for i in range(n)]


def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    N, p = data[0], data[1]
    vals = data[2:]
    A = [vals[i * N:(i + 1) * N] for i in range(N)]

    if p == 1:
        sys.stdout.write("\n".join(" ".join(["0"] * N) for _ in range(N)))
        return

    if p == 2:
        B = [[1 if x == 0 else x & 1 for x in row] for row in A]
        ans = square_mod2(B)
        sys.stdout.write("\n".join(" ".join(map(str, row)) for row in ans))
        return

    C = []
    zeros = []
    diag_zeros = []
    offdiag_zeros = [] if p == 3 else None

    for i in range(N):
        row = []
        for j in range(N):
            v = A[i][j]
            if v == 0:
                zeros.append((i, j))
                if i == j:
                    diag_zeros.append(i)
                elif p == 3:
                    offdiag_zeros.append((i, j))
                row.append(0)
            else:
                row.append(v)
        C.append(row)

    K = len(zeros)

    if K == N * N:
        sys.stdout.write("\n".join(" ".join(["0"] * N) for _ in range(N)))
        return

    ans = matrix_power(C, p, p)

    if p == 3:
        for i, j in offdiag_zeros:
            ans[i][j] = (ans[i][j] + C[j][i]) % p

    for i in diag_zeros:
        for r in range(N):
            ans[r][i] = (ans[r][i] + C[r][i]) % p
        for c in range(N):
            ans[i][c] = (ans[i][c] + C[i][c]) % p

    if K & 1:
        for i in range(N):
            row = ans[i]
            for j in range(N):
                if row[j]:
                    row[j] = p - row[j]

    sys.stdout.write("\n".join(" ".join(map(str, row)) for row in ans))


if __name__ == "__main__":
    solve()

import sys
import heapq

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    N, M, A, B = data[0], data[1], data[2], data[3]
    intervals = []
    idx = 4
    for _ in range(M):
        L = data[idx]
        R = data[idx+1]
        idx += 2
        intervals.append((L, R))

    if A == B:
        c = A
        if (N - 1) % c != 0:
            print("No")
            return
        for L, R in intervals:
            rem = (L - 1) % c
            if rem != 0:
                L += c - rem
            if L <= R:
                print("No")
                return
        print("Yes")
        return

    intervals.sort()
    merged = []
    for L, R in intervals:
        if not merged or L > merged[-1][1] + 1:
            merged.append([L, R])
        else:
            if R > merged[-1][1]:
                merged[-1][1] = R

    for L, R in merged:
        if R - L + 1 >= B:
            print("No")
            return

    INF = 10**30
    dist = [INF] * A
    dist[0] = 0
    heap = [(0, 0)]
    while heap:
        d, r = heapq.heappop(heap)
        if d != dist[r]:
            continue
        for step in range(A, B + 1):
            nr = (r + step) % A
            nd = d + step
            if nd < dist[nr]:
                dist[nr] = nd
                heapq.heappush(heap, (nd, nr))

    T = max(dist)
    max_exact = int(T) + 2 * B + 5
    rep_small = [False] * (max_exact + 1)
    for d in range(max_exact + 1):
        rep_small[d] = (d >= dist[d % A])

    maskB = (1 << B) - 1

    f_masks = [[0] * (B + 1) for _ in range(B)]
    for k in range(B):
        for mf in range(1, B + 1):
            ds = A
            min_d = k + 1
            if ds < min_d:
                ds = min_d
            de = B
            max_d = k + mf
            if de > max_d:
                de = max_d
            if ds <= de:
                off_start = ds - k - 1
                off_end = de - k - 1
                f_masks[k][mf] = ((1 << (off_end - off_start + 1)) - 1) << off_start

    def reachable_mask_from_seeds(seeds, length, dist=dist, A=A, B=B, T=T, max_exact=max_exact, rep_small=rep_small):
        if seeds == 0 or length <= 0:
            return 0
        valid = B if B < length else length
        seeds &= (1 << valid) - 1
        if seeds == 0:
            return 0
        max_s = seeds.bit_length() - 1
        lo = length - B
        if lo < 0:
            lo = 0
        count = valid
        if lo - max_s >= T:
            return (1 << count) - 1

        seed_offsets = []
        mm = seeds
        while mm:
            lsb = mm & -mm
            seed_offsets.append(lsb.bit_length() - 1)
            mm -= lsb

        mask = 0
        for k in range(count):
            o = length - 1 - k
            for s in seed_offsets:
                if s > o:
                    break
                d = o - s
                if d <= max_exact:
                    if rep_small[d]:
                        mask |= 1 << k
                        break
                else:
                    if d >= dist[d % A]:
                        mask |= 1 << k
                        break
        return mask

    def advance_good(state, length, f_masks=f_masks, maskB=maskB, B=B, reachable=reachable_mask_from_seeds):
        if length <= 0:
            return state
        mf = B if B < length else length
        F = 0
        mm = state
        while mm:
            lsb = mm & -mm
            k = lsb.bit_length() - 1
            F |= f_masks[k][mf]
            mm -= lsb
        inside = reachable(F, length)
        if length < B:
            return ((state << length) | inside) & maskB
        return inside & maskB

    state = 1
    p = 1
    for L, R in merged:
        good_len = L - 1 - p
        if good_len > 0:
            state = advance_good(state, good_len)
            p = L - 1
            if state == 0 and p < N:
                print("No")
                return
        else:
            p = L - 1

        bad_len = R - L + 1
        state = (state << bad_len) & maskB
        p = R
        if state == 0 and p < N:
            print("No")
            return

    good_len = N - p
    if good_len > 0:
        state = advance_good(state, good_len)
        p = N

    print("Yes" if (state & 1) else "No")

