    solve()

from typing import List
from bisect import bisect_left

class Solution:
    def maximumWeight(self, intervals: List[List[int]]) -> List[int]:
        n = len(intervals)

        # Sort by right endpoint.  Store (right, left, weight, original_index).
        arr = sorted((r, l, w, idx) for idx, (l, r, w) in enumerate(intervals))
        rs = [item[0] for item in arr]

        # p[i] = number of intervals ending strictly before interval i starts.
        # Arrays are 1-based for DP convenience.
        p_list = [0] + [bisect_left(rs, item[1]) for item in arr]
        w_list = [0] + [item[2] for item in arr]
        idx_list = [0] + [item[3] for item in arr]

        del arr, rs

        def add_idx(tup, x):
            """Insert x into a sorted tuple of length at most 3."""
            m = len(tup)
            if m == 0:
                return (x,)
            if m == 1:
                a = tup[0]
                if x < a:
                    return (x, a)
                return (a, x)
            if m == 2:
                a, b = tup
                if x < a:
                    return (x, a, b)
                if x < b:
                    return (a, x, b)
                return (a, b, x)
            if m == 3:
                a, b, c = tup
                if x < a:
                    return (x, a, b, c)
                if x < b:
                    return (a, x, b, c)
                if x < c:
                    return (a, b, x, c)
                return (a, b, c, x)

            # Fallback, not needed for k <= 4.
            pos = bisect_left(tup, x)
            return tup[:pos] + (x,) + tup[pos:]

        # DP for exactly t intervals.
        # prev_* corresponds to t-1, curr_* to t.
        prev_score = [0] * (n + 1)
        prev_tuple = [()] * (n + 1)

        best_score = 0
        best_tuple = ()

        for _ in range(1, 5):
            curr_score = [-1] * (n + 1)
            curr_tuple = [()] * (n + 1)

            for i in range(1, n + 1):
                # Option 1: do not take interval i.
                bs = curr_score[i - 1]
                bt = curr_tuple[i - 1]

                # Option 2: take interval i.
                pi = p_list[i]
                prev_s = prev_score[pi]
                if prev_s != -1:
                    cand_s = prev_s + w_list[i]
                    if cand_s > bs:
                        bs = cand_s
                        bt = add_idx(prev_tuple[pi], idx_list[i])
                    elif cand_s == bs:
                        cand_t = add_idx(prev_tuple[pi], idx_list[i])
                        if cand_t < bt:
                            bt = cand_t

                curr_score[i] = bs
                curr_tuple[i] = bt

            final_s = curr_score[n]
            final_t = curr_tuple[n]

            if final_s > best_score or (final_s == best_score and final_t < best_tuple):
                best_score = final_s
                best_tuple = final_t

            prev_score, prev_tuple = curr_score, curr_tuple

        return list(best_tuple)

import sys


def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    N, M = data[0], data[1]
    A = [x - 1 for x in data[2:2 + N]]

    MOD = 998244353

    indeg = [0] * N
    for a in A:
        indeg[a] += 1

    q = [i for i in range(N) if indeg[i] == 0]
    head = 0
    prod = [None] * N

    M1 = M + 1
    cs = list(range(1, M1))
    base = [0] + cs
    base_copy = base.copy
    mod = MOD
    append = q.append

    while head < len(q):
        u = q[head]
        head += 1
        p = A[u]

        arr = prod[u]
        par = prod[p]

        if par is None:
            if arr is None:
                prod[p] = base_copy()
            else:
                s = 0
                for c in cs:
                    s += arr[c]
                    if s >= mod:
                        s -= mod
                    arr[c] = s
                prod[p] = arr
                prod[u] = None
        else:
            if arr is None:
                for c in cs:
                    par[c] = (par[c] * c) % mod
            else:
                s = 0
                for c in cs:
                    s += arr[c]
                    if s >= mod:
                        s -= mod
                    par[c] = (par[c] * s) % mod
                prod[u] = None

        indeg[p] -= 1
        if indeg[p] == 0:
            append(p)

    visited = [False] * N
    ans = 1

    for i in range(N):
        if indeg[i] > 0 and not visited[i]:
            cyc = []
            v = i
            while not visited[v]:
                visited[v] = True
                cyc.append(v)
                v = A[v]

            comp = None
            for v in cyc:
                hv = prod[v]
                if hv is None:
                    continue
                if comp is None:
                    comp = hv
                else:
                    for c in cs:
                        comp[c] = (comp[c] * hv[c]) % mod

            if comp is None:
                total = M % mod
            else:
                total = sum(comp) % mod

            ans = (ans * total) % mod

    print(ans)


if __name__ == "__main__":
    solve()

