import sys


def main():
    data = sys.stdin.buffer.read().split()
    if len(data) < 3:
        return

    K = int(data[0])
    S = data[1]
    T = data[2]

    n = len(S)
    m = len(T)

    if abs(n - m) > K:
        print("No")
        return

    if K == 0:
        print("Yes" if S == T else "No")
        return

    # Always possible by substituting min(n, m) characters and inserting/deleting the rest.
    if max(n, m) <= K:
        print("Yes")
        return

    target = n - m  # final diagonal: i - j
    size = 2 * K + 3
    offset = K + 1
    NEG = -1

    s = S
    t = T
    nn = n
    mm = m

    # Extend along diagonal d while characters match.
    def extend(x, d, s=s, t=t, nn=nn, mm=mm):
        y = x - d
        if y < 0 or y >= mm:
            return x, y

        limit = nn
        md = mm + d
        if md < limit:
            limit = md

        while x < limit and s[x] == t[y]:
            x += 1
            y += 1
        return x, y

    prev = [NEG] * size

    x, y = extend(0, 0)
    prev[offset] = x
    if x == nn and y == mm:
        print("Yes")
        return

    for e in range(1, K + 1):
        curr = [NEG] * size

        # Prune diagonals that cannot reach the target diagonal within remaining edits.
        rem = K - e
        low = max(-e, target - rem)
        high = min(e, target + rem)
        if low > high:
            break

        # Check the target diagonal first; it is the only one that can immediately succeed.
        if low <= target <= high:
            order = [target]
            for d in range(low, high + 1):
                if d != target:
                    order.append(d)
        else:
            order = range(low, high + 1)

        prev_low = 1 - e
        prev_high = e - 1
        reachable = False

        for d in order:
            best = NEG

            # Carry over, and substitute from the same diagonal.
            if prev_low <= d <= prev_high:
                v = prev[offset + d]
                if v >= 0:
                    yprev = v - d
                    if 0 <= yprev <= mm:
                        if v > best:
                            best = v
                        if v < nn and yprev < mm:
                            nv = v + 1
                            if nv > best:
                                best = nv

            # Insert: from diagonal d + 1, x unchanged.
            dp1 = d + 1
            if prev_low <= dp1 <= prev_high:
                v = prev[offset + dp1]
                if v >= 0:
                    yprev = v - dp1
                    if 0 <= yprev < mm:
                        if v > best:
                            best = v

            # Delete: from diagonal d - 1, x increases by 1.
            dm1 = d - 1
            if prev_low <= dm1 <= prev_high:
                v = prev[offset + dm1]
                if v >= 0:
                    yprev = v - dm1
                    if v < nn and 0 <= yprev <= mm:
                        nv = v + 1
                        if nv > best:
                            best = nv

            if best >= 0:
                reachable = True
                best, y = extend(best, d)
                curr[offset + d] = best
                if best == nn and y == mm:
                    print("Yes")
                    return

        if not reachable:
            break

        prev = curr

    print("No")


if __name__ == "__main__":
    main()

import sys


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    n = data[0]
    A = data[1:1 + n]
    del data

    if not A:
        print(0)
        return

    n = len(A)
    total = sum(A)

    # Sum of all pair sums (i <= j): each A_i appears (N+1) times.
    ans = (n + 1) * total

    max_sum = 2 * max(A)
    K = max_sum.bit_length() - 1

    # Use direct arrays while the modulus is reasonably small.
    ARRAY_LIMIT = 1 << 20

    arr = A
    M = 1

    for k in range(1, K + 1):
        M <<= 1
        mask = M - 1

        if M <= ARRAY_LIMIT:
            cnt = [0] * M
            sm = [0] * M
            seen = []
            append = seen.append

            for a in arr:
                r = a & mask
                c = cnt[r]
                if c:
                    cnt[r] = c + 1
                    sm[r] += a
                else:
                    cnt[r] = 1
                    sm[r] = a
                    append(r)

            T = 0
            half = M >> 1

            for r in seen:
                c = cnt[r]
                s = sm[r]

                if r < half:
                    if r == 0:
                        T += (c + 1) * s
                    else:
                        comp = M - r
                        cc = cnt[comp]
                        if cc:
                            T += c * sm[comp] + cc * s
                elif r == half:
                    T += (c + 1) * s

            del cnt, sm, seen, append

        else:
            d = {}
            get = d.get

            for a in arr:
                r = a & mask
                v = get(r)
                if v is None:
                    d[r] = [1, a]
                else:
                    v[0] += 1
                    v[1] += a

            T = 0
            half = M >> 1
            get = d.get

            for r, v in d.items():
                c = v[0]
                s = v[1]

                if r < half:
                    if r == 0:
                        T += (c + 1) * s
                    else:
                        w = get(M - r)
                        if w is not None:
                            T += c * w[1] + w[0] * s
                elif r == half:
                    T += (c + 1) * s

            del d, get

        ans -= T >> k

        # If no pair sum is divisible by 2^k, none will be for larger k.
        if T == 0:
            break

    sys.stdout.write(str(ans) + "\n")


if __name__ == "__main__":
    main()

from typing import List

class Solution:
    def countComponents(self, nums: List[int], threshold: int) -> int:
        T = threshold
        if T <= 0:
            return len(nums)

        present = bytearray(T + 1)
        greater = 0
        present_count = 0

        for x in nums:
            if x <= T:
                if not present[x]:
                    present[x] = 1
                    present_count += 1
            else:
                greater += 1

        # Values greater than threshold are isolated.
        comps = present_count + greater

        if present_count <= 1:
            return comps

        # If 1 is present, every value <= threshold is connected to it.
        if present[1]:
            return 1 + greater

        parent = list(range(T + 1))
        size = [1] * (T + 1)

        # rep[m] stores a DSU representative of a component that contains
        # at least one present divisor of m.
        rep = [0] * (T + 1)

        par = parent
        sz = size
        rep_arr = rep
        pres = present

        for d in range(1, T + 1):
            if not pres[d]:
                continue

            root_d = d
            while par[root_d] != root_d:
                par[root_d] = par[par[root_d]]
                root_d = par[root_d]

            for m in range(d, T + 1, d):
                r = rep_arr[m]

                if r == 0:
                    rep_arr[m] = root_d
                elif r != root_d:
                    rr = r
                    while par[rr] != rr:
                        par[rr] = par[par[rr]]
                        rr = par[rr]

                    if rr != root_d:
                        if sz[root_d] < sz[rr]:
                            par[root_d] = rr
                            sz[rr] += sz[root_d]
                            root_d = rr
                        else:
                            par[rr] = root_d
                            sz[root_d] += sz[rr]
                        comps -= 1

                    rep_arr[m] = root_d

        return comps
